import hmac
import hashlib
import base64
import json
import unicodedata
import re
import os
from typing import Optional, Dict, Any


class TokenVerifier:
    """Verifies JWT tokens for API gateway authentication.
    Supports both HMAC (HS256) and RSA (RS256) algorithms.
    """

    def __init__(self, config: Dict[str, Any]):
        self.hmac_secret = config['hmac_secret'].encode('utf-8')
        self.rsa_public_key = config.get('rsa_public_key')  # PEM format
        self.allowed_algorithms = frozenset(['HS256', 'RS256'])
        self.issuer = config['issuer']
        self.audience = config['audience']
        self.clock_skew_seconds = config.get('clock_skew_seconds', 30)

    def _base64url_decode(self, data: str) -> bytes:
        """RFC 7515 compliant base64url decoding."""
        # Add padding if necessary
        padding = 4 - len(data) % 4
        if padding != 4:
            data += '=' * padding
        return base64.urlsafe_b64decode(data)

    def _base64url_encode(self, data: bytes) -> str:
        """RFC 7515 compliant base64url encoding."""
        return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')

    def _normalize_and_validate_alg(self, value: str) -> Optional[str]:
        """Validate algorithm value strictly - only allow exact ASCII matches.
        No normalization needed since we only accept exact known values.
        """
        # Strip and check for exact match only - no Unicode normalization
        stripped = value.strip()
        if stripped in self.allowed_algorithms:
            return stripped
        return None

    def _verify_hs256(self, signing_input: bytes, signature: bytes) -> bool:
        """Verify HMAC-SHA256 signature."""
        expected = hmac.new(self.hmac_secret, signing_input, hashlib.sha256).digest()
        return hmac.compare_digest(expected, signature)

    def _verify_rs256(self, signing_input: bytes, signature: bytes) -> bool:
        """Verify RSA-SHA256 signature.
        Requires the cryptography library for RSA operations.
        """
        if not self.rsa_public_key:
            return False
        try:
            from cryptography.hazmat.primitives import hashes, serialization
            from cryptography.hazmat.primitives.asymmetric import padding
            key = serialization.load_pem_public_key(self.rsa_public_key.encode())
            key.verify(signature, signing_input, padding.PKCS1v15(), hashes.SHA256())
            return True
        except Exception:
            return False

    def _validate_claims(self, payload: Dict[str, Any], current_time: int) -> bool:
        """Validate standard JWT claims (iss, aud, exp, nbf)."""
        # Verify issuer
        if payload.get('iss') != self.issuer:
            return False
        # Verify audience
        aud = payload.get('aud')
        if isinstance(aud, list):
            if self.audience not in aud:
                return False
        elif aud != self.audience:
            return False
        # Verify expiration
        exp = payload.get('exp')
        if exp is not None and current_time > exp + self.clock_skew_seconds:
            return False
        # Verify not-before
        nbf = payload.get('nbf')
        if nbf is not None and current_time < nbf - self.clock_skew_seconds:
            return False
        return True

    def verify_token(self, token: str, current_time: int) -> Optional[Dict[str, Any]]:
        """Verify a JWT token and return the payload if valid.

        Returns None if verification fails for any reason.
        Implements defense-in-depth with algorithm validation.
        """
        try:
            parts = token.split('.')
            if len(parts) != 3:
                return None

            # Decode header
            header_bytes = self._base64url_decode(parts[0])
            header = json.loads(header_bytes)

            # Extract and strictly validate algorithm
            raw_alg = header.get('alg', '')
            alg = self._normalize_and_validate_alg(str(raw_alg))

            # Reject if algorithm is not exactly in allowed set
            if alg is None:
                return None

            # Decode payload
            payload_bytes = self._base64url_decode(parts[1])
            payload = json.loads(payload_bytes)

            # Decode signature
            signature = self._base64url_decode(parts[2])

            # Construct signing input per RFC 7515
            signing_input = f"{parts[0]}.{parts[1]}".encode('ascii')

            # Verify signature based on algorithm
            if alg == 'HS256':
                if not self._verify_hs256(signing_input, signature):
                    return None
            elif alg == 'RS256':
                if not self._verify_rs256(signing_input, signature):
                    return None

            # Validate claims
            if not self._validate_claims(payload, current_time):
                return None

            return payload

        except (json.JSONDecodeError, UnicodeDecodeError, ValueError, KeyError):
            return None


class ResourceAccessController:
    """Controls access to protected resources based on JWT claims."""

    def __init__(self, verifier: TokenVerifier):
        self.verifier = verifier
        self._permission_cache: Dict[str, Dict[str, Any]] = {}

    def _sanitize_resource_path(self, path: str) -> str:
        """Sanitize resource path to prevent traversal attacks."""
        # Normalize Unicode first
        normalized = unicodedata.normalize('NFKC', path)
        # Remove null bytes
        normalized = normalized.replace('\x00', '')
        # Collapse path separators and resolve traversal
        parts = []
        for segment in normalized.split('/'):
            if segment == '..':
                if parts:
                    parts.pop()
            elif segment and segment != '.':
                parts.append(segment)
        return '/' + '/'.join(parts)

    def check_access(self, token: str, resource_path: str, 
                     current_time: int) -> bool:
        """Check if the token grants access to the specified resource."""
        payload = self.verifier.verify_token(token, current_time)
        if payload is None:
            return False

        safe_path = self._sanitize_resource_path(resource_path)

        # Check resource permissions from token claims
        permissions = payload.get('permissions', [])
        subject = payload.get('sub', '')

        for perm in permissions:
            if self._matches_resource(perm, safe_path):
                return True

        return False

    def _matches_resource(self, permission: str, resource: str) -> bool:
        """Check if a permission pattern matches a resource path.
        Supports glob-style wildcards in permission strings.
        """
        # Convert permission pattern to regex safely
        regex_parts = []
        for char in permission:
            if char == '*':
                regex_parts.append('[^/]*')
            elif char == '?':
                regex_parts.append('[^/]')
            else:
                regex_parts.append(re.escape(char))
        pattern = '^' + ''.join(regex_parts) + '$'
        return bool(re.match(pattern, resource))
